(function(){'use strict';var DB_NAME='mowology-actions';var DB_VERSION=1;var STORE_NAME='pending-actions';var MAX_RETRIES=5;var QUEUED_ENDPOINTS=['/crm/api/time-clock.php','/crm/api/pow-actions.php','/crm/api/job-timer.php'];var _db=null;function openDB(){return new Promise(function(resolve,reject){if(_db){resolve(_db);return}
if(!window.indexedDB){reject(new Error('IndexedDB not supported'));return}
var req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=function(e){var database=e.target.result;if(!database.objectStoreNames.contains(STORE_NAME)){database.createObjectStore(STORE_NAME,{keyPath:'id',autoIncrement:!0})}};req.onsuccess=function(e){_db=e.target.result;resolve(_db)};req.onerror=function(){reject(new Error('Failed to open IndexedDB'))}})}
function addRecord(record){return openDB().then(function(database){return new Promise(function(resolve,reject){var tx=database.transaction(STORE_NAME,'readwrite');var req=tx.objectStore(STORE_NAME).add(record);req.onsuccess=function(){resolve(req.result)};req.onerror=function(){reject(req.error)}})})}
function getAllRecords(){return openDB().then(function(database){return new Promise(function(resolve){var tx=database.transaction(STORE_NAME,'readonly');var req=tx.objectStore(STORE_NAME).getAll();req.onsuccess=function(){resolve(req.result||[])};req.onerror=function(){resolve([])}})})}
function deleteRecord(id){return openDB().then(function(database){return new Promise(function(resolve){var tx=database.transaction(STORE_NAME,'readwrite');tx.objectStore(STORE_NAME).delete(id);tx.oncomplete=function(){resolve()};tx.onerror=function(){resolve()}})})}
function getPendingCount(){return openDB().then(function(database){return new Promise(function(resolve){var tx=database.transaction(STORE_NAME,'readonly');var req=tx.objectStore(STORE_NAME).count();req.onsuccess=function(){resolve(req.result)};req.onerror=function(){resolve(0)}})}).catch(function(){return 0})}
function isOnline(){if(window.MwNative&&typeof window.MwNative.network==='object'){return window.MwNative.network.isOnline!==!1}
return navigator.onLine!==!1}
function guessLabel(url,body){if(url.indexOf('time-clock')!==-1){if(body&&body.action==='clock_in')return'Clock In';if(body&&body.action==='clock_out')return'Clock Out';return'Time Clock'}
if(url.indexOf('pow-actions')!==-1){if(body&&body.action==='start_visit')return'Start Visit';if(body&&body.action==='end_visit')return'Complete Visit';if(body&&body.action==='save_notes')return'Save Notes';return'Visit Update'}
if(url.indexOf('job-timer')!==-1){if(body&&body.action==='start')return'Start Timer';if(body&&body.action==='stop')return'Stop Timer';return'Job Timer'}
return'Action'}
function buildOptimisticResponse(url,body){var base={success:!0,offline:!0,queued:!0};if(url.indexOf('job-timer')!==-1){if(body&&body.action==='start'){return Object.assign({},base,{entry_id:0,tracking_level:'standard',require_photos:!1})}
return Object.assign({},base,{duration_formatted:'—'})}
if(url.indexOf('time-clock')!==-1){if(body&&body.action==='clock_in'){return Object.assign({},base,{entry_id:0,clocked_in:!0})}
return Object.assign({},base,{clocked_in:!1})}
return base}
function queueAction(url,options){var bodyStr=(options&&options.body)||'';var bodyObj=null;try{bodyObj=typeof bodyStr==='string'?JSON.parse(bodyStr):null}catch(e){}
var record={endpoint:url,method:(options&&options.method)||'POST',body:bodyObj,bodyRaw:typeof bodyStr==='string'?bodyStr:null,headers:(options&&options.headers)||{},label:guessLabel(url,bodyObj),timestamp:Date.now(),retries:0};return addRecord(record).then(function(){registerSync();updateUI()})}
function replayOne(record){var opts={method:record.method||'POST',credentials:'include',headers:{}};if(record.bodyRaw){opts.body=record.bodyRaw;opts.headers['Content-Type']='application/json'}else if(record.body){opts.body=JSON.stringify(record.body);opts.headers['Content-Type']='application/json'}
var origHeaders=record.headers||{};Object.keys(origHeaders).forEach(function(k){if(!opts.headers[k])opts.headers[k]=origHeaders[k]});var realFetch=window._mwOrigFetch||window.fetch;return realFetch(record.endpoint,opts).then(function(res){if(res.ok){return deleteRecord(record.id).then(function(){return!0})}
return!1}).catch(function(){return!1})}
function syncNow(){if(!isOnline())return Promise.resolve({replayed:0,failed:0});return getAllRecords().then(function(records){if(!records.length)return{replayed:0,failed:0};var replayed=0,failed=0;var chain=records.reduce(function(p,record){return p.then(function(){return replayOne(record).then(function(ok){if(ok)replayed++;else failed++})})},Promise.resolve());return chain.then(function(){updateUI();return{replayed:replayed,failed:failed}})})}
function updateUI(){getPendingCount().then(function(count){try{localStorage.setItem('mw-action-queue-count',String(count))}catch(e){}
var badge=document.getElementById('mwClockQueueBadge');if(badge){badge.textContent=count>0?count:'';badge.classList.toggle('mw-queue-has-items',count>0)}
var strip=document.getElementById('mwOfflineStrip');var text=document.getElementById('mwOfflineStripText');if(!strip)return;if(!isOnline()){strip.className='mw-mc-offline-strip mw-offline-state-offline';strip.style.display='flex';if(text){text.textContent=count>0?count+' action'+(count!==1?'s':'')+' queued — will sync when you reconnect':'You\'re offline — actions will queue automatically'}}else if(count>0){strip.className='mw-mc-offline-strip mw-offline-state-syncing';strip.style.display='flex';if(text)text.textContent='Syncing '+count+' action'+(count!==1?'s':'')+'…'}else{strip.className='mw-mc-offline-strip mw-offline-state-clear';strip.style.display='flex';if(text)text.textContent='✓ All synced';setTimeout(function(){if(strip.classList.contains('mw-offline-state-clear')){strip.style.display='none';strip.className='mw-mc-offline-strip'}},2500)}})}
function registerSync(){if('serviceWorker' in navigator&&'SyncManager' in window){navigator.serviceWorker.ready.then(function(reg){return reg.sync.register('action-queue-sync')}).catch(function(){})}}
var _origFetch=window.fetch;window._mwOrigFetch=_origFetch;window.fetch=function(resource,options){var url=typeof resource==='string'?resource:(resource&&resource.url)||'';var method=((options&&options.method)||'GET').toUpperCase();var shouldQueue=method==='POST'&&QUEUED_ENDPOINTS.some(function(ep){return url.indexOf(ep)!==-1})&&!isOnline();if(!shouldQueue){return _origFetch.apply(window,arguments)}
var bodyStr=(options&&options.body)||'';var bodyObj=null;try{bodyObj=typeof bodyStr==='string'?JSON.parse(bodyStr):null}catch(e){}
return queueAction(url,options).then(function(){var fakeData=buildOptimisticResponse(url,bodyObj);return new Response(JSON.stringify(fakeData),{status:200,headers:{'Content-Type':'application/json'}})}).catch(function(){return _origFetch.apply(window,arguments)})};var _offlineQueueAbort=new AbortController();var _signal={signal:_offlineQueueAbort.signal};window.addEventListener('online',function(){updateUI();syncNow().then(function(result){if(result.replayed>0)updateUI();})},_signal);window.addEventListener('offline',function(){updateUI()},_signal);window.addEventListener('pagehide',function(){try{_offlineQueueAbort.abort()}catch(e){}},{once:!0});document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible'&&isOnline()){getPendingCount().then(function(count){if(count>0)syncNow().then(updateUI);})}},_signal);window.addEventListener('focus',function(){if(isOnline()){getPendingCount().then(function(count){if(count>0)syncNow().then(updateUI);})}},_signal);if(window.MwNative&&window.MwNative.network){window.MwNative.network.onStatusChange(function(connected){if(connected){syncNow().then(updateUI)}else{updateUI()}})}
if('serviceWorker' in navigator){navigator.serviceWorker.addEventListener('message',function(e){if(e.data&&e.data.type==='action-queue-flush'){syncNow().then(updateUI)}
if(e.data&&e.data.type==='receipts-synced'){if(window.OfflineReceipts)window.OfflineReceipts.updatePendingBadge();}})}
openDB().then(function(){updateUI();if(isOnline()){getPendingCount().then(function(count){if(count>0)syncNow().then(updateUI);})}}).catch(function(){});window.OfflineActions={syncNow:syncNow,getPendingCount:getPendingCount,updateUI:updateUI}})()